from gen_more_ww1 import *

M("uboat_1917", 1917, 2, "Sınırsız Denizaltı Savaşı Yeniden || Unrestricted Submarine Warfare Resumes",
  "Almanya 1 Şubat'ta tarafsızlar dahil tüm gemilere saldırmaya başladı. Hedef İngiltere'yi altı ayda boğmak; bedel Amerika'nın savaşa girmesi olabilir. Zimmermann Telgrafı'nın ortaya çıkması da an meselesi. || On 1 February Germany began attacking all ships, neutrals included. The aim is to starve Britain within six months; the price may be American entry into the war. The Zimmermann Telegram is about to come to light too.",
  [["gold", "United Kingdom", -1.0], ["rel", "Germany", "United States of America", -10]],
  {"Germany": R("Amirallere göre altı ayda İngiltere diz çökecek. Ama Amerikan sanayisi sınırsızdır. || The admirals say Britain will kneel in six months. But American industry is limitless.",
                O("Sınırsız harbi başlat (tarihî) || Begin unrestricted warfare (historical)", "Büyük kumar || A great gamble", "U-botlar her gemiyi vurmaya başladı. || U-boats began sinking every ship.", [["gold", "United Kingdom", -1.5], ["rel", "Germany", "United States of America", -12], ["buff", "Germany", "att", 1.05, 12]]),
                O("Sınırlı harpte kal || Keep it restricted", "ABD tarafsız kalır || The US stays neutral", "Berlin denizaltı harbini sınırlı tuttu. || Berlin kept the submarine war limited.", [["rel", "Germany", "United States of America", 4], ["stab", "Germany", -2]])),
   "United Kingdom": R("Gemi kayıpları dayanılmaz; yiyecek stokları haftalara düştü. Konvoy sistemi önerisi masada. || Shipping losses are unbearable; food stocks are down to weeks. A convoy system is on the table.",
                O("Konvoy sistemi kur (tarihî) || Introduce convoys (historical)", "Kayıplar düşer || Losses fall", "Amirallik konvoy sistemini zorunlu kıldı. || The Admiralty made convoys compulsory.", [["gold", "United Kingdom", 1.0], ["stab", "United Kingdom", 3]]),
                O("Gemileri tek tek yolla || Sail ships singly", "Kayıp artar || Losses mount", "Kayıplar artmaya devam etti. || Losses kept mounting.", [["gold", "United Kingdom", -1.0], ["stab", "United Kingdom", -3]])),
   "United States of America": R("Alman denizaltıları Amerikan gemilerini batırıyor. Kongre tarafsızlık ile savaş arasında bölünmüş durumda. || German submarines are sinking American ships. Congress is divided between neutrality and war.",
                O("Almanya ile ilişkiyi kes (tarihî) || Break relations with Germany (historical)", "Savaşa yaklaş || Edge toward war", "Washington Berlin ile ilişkileri kesti. || Washington severed relations with Berlin.", [["rel", "United States of America", "Germany", -12], ["rel", "United States of America", "United Kingdom", 8]]),
                O("Silahlı tarafsızlık || Armed neutrality", "Ticaret gemilerini silahlandır || Arm merchant ships", "Amerikan ticaret gemileri silahlandırıldı. || American merchant ships were armed.", [["rel", "United States of America", "Germany", -5]]))},
  icon="submarine", scene="pre_naval")

M("passchendaele", 1917, 7, "Passchendaele || Passchendaele",
  "Haig, Flandre'de Üçüncü Ypres Muharebesi'ni başlattı: yağmur ve topçu ateşi araziyi dizlere kadar çamura çevirdi. Birkaç kilometre için yüz binlerce kayıp verilecek. || Haig launched the Third Battle of Ypres in Flanders: rain and shellfire turned the ground into knee-deep mud. Hundreds of thousands will fall for a few kilometres.",
  [["troops", "United Kingdom", -6], ["troops", "Germany", -5], ["stab", "United Kingdom", -2]],
  {"United Kingdom": R("Haig Belçika kıyısına ulaşıp U-bot üslerini ele geçirmek istiyor. Yağmur mevsimi başlıyor. || Haig wants to reach the Belgian coast and take the U-boat bases. The rainy season is starting.",
                O("Taarruzu sürdür (tarihî) || Press on (historical)", "Büyük kayıplar || Huge losses", "Müttefikler Passchendaele köyünü zorlu bir bedelle aldı. || The Allies took Passchendaele village at terrible cost.", [["buff", "United Kingdom", "att", 1.1, 10], ["troops", "United Kingdom", -8], ["stab", "United Kingdom", -3]]),
                O("Taarruzu kısıtla || Limit the attack", "Kayıp az, kazanç az || Fewer losses, smaller gains", "Haig sınırlı hedeflerle yetindi. || Haig settled for limited objectives.", [["stab", "United Kingdom", 1]])),
   "Germany": R("İngiliz taarruzu çamurda tıkandı, ama savunma hatları da eriyor. || The British attack is bogged down in mud, but your defences are wearing thin too.",
                O("Derinlemesine savunma (tarihî) || Defence in depth (historical)", "Çamur savunmacının yanında || The mud favours the defender", "Alman savunması çamurda İngilizleri yıprattı. || The German defence ground the British down in the mud.", [["buff", "Germany", "def", 1.2, 12], ["troops", "Germany", -3]]),
                O("Karşı saldırı yap || Counterattack", "Büyük risk || High risk", "Alman karşı saldırıları pahalıya patladı. || German counterattacks proved costly.", [["troops", "Germany", -6], ["buff", "Germany", "att", 1.05, 6]]))},
  icon="helmet_ww1", scene="ww1_assault")

M("caporetto", 1917, 10, "Caporetto || Caporetto",
  "Alman tümenleri ve gaz topçusuyla desteklenen Avusturya taarruzu İtalyan hattını Caporetto'da yardı. İtalyan ordusu Piave'ye kadar çekiliyor; yüz binlerce esir ve kayıp. || An Austrian attack backed by German divisions and gas artillery broke the Italian line at Caporetto. The Italian army is falling back to the Piave; hundreds of thousands are lost or captured.",
  [["troops", "Italy", -10], ["stab", "Italy", -6], ["troops", "Austria", -2]],
  {"Italy": R("Cadorna görevden alındı. Hatları Piave'de toplamak şart; müttefik tümenleri yolda. || Cadorna was dismissed. The lines must be rallied on the Piave; Allied divisions are on their way.",
               O("Piave'de savun (tarihî) || Defend on the Piave (historical)", "Ulusal direniş || National resistance", "İtalya Piave hattında dayandı. || Italy held on the Piave line.", [["buff", "Italy", "def", 1.25, 20], ["stab", "Italy", 4], ["rel", "Italy", "United Kingdom", 5]]),
               O("Barış ara || Seek peace", "Müttefiklerle ilişki bozulur || Ties with allies suffer", "Roma gizlice barış yoklaması yaptı. || Rome secretly probed for peace.", [["stab", "Italy", -4], ["rel", "Italy", "United Kingdom", -8], ["rel", "Italy", "Germany", 4]])),
   "Austria": R("Alman desteği zaferi getirdi; şimdi Venedik'e mi yürüyeceksin, yoksa ikmal sınırlarını mı koruyacaksın? || German support brought victory; will you march on Venice now, or respect your supply limits?",
               O("Piave'ye kadar ilerle (tarihî) || Advance to the Piave (historical)", "Zafer, ama ikmal zorlanır || Victory, but supply strains", "Avusturya Piave'ye ulaştı ve durdu. || Austria reached the Piave and stopped.", [["buff", "Austria", "att", 1.1, 8], ["stab", "Austria", 4]]),
               O("Venedik'e yüklen || Strike for Venice", "Cesur ama riskli || Bold but risky", "Avusturya birlikleri Venedik ovasına girdi. || Austrian troops entered the Venetian plain.", [["troops", "Austria", -4], ["buff", "Austria", "att", 1.2, 8], ["stab", "Austria", 2]]))},
  icon="tank", scene="ww1_assault")

M("jerusalem", 1917, 12, "Kudüs Düştü || Jerusalem Falls",
  "Allenby'nin ordusu Gazze-Birüssebi hattını yararak Kudüs'e girdi. Balfour Deklarasyonu iki hafta önce yayımlandı. Filistin'de Osmanlı hâkimiyeti çöküyor. || Allenby's army broke the Gaza–Beersheba line and entered Jerusalem. The Balfour Declaration was published weeks earlier. Ottoman rule in Palestine is collapsing.",
  [["stab", "Turkey", -5], ["stab", "United Kingdom", 4]],
  {"Turkey": R("Kudüs kaybedildi; Filistin cephesi çöküyor. Yıldırım Orduları Grubu'nun kaderi sende. || Jerusalem is lost; the Palestine front is collapsing. The fate of the Yildirim Army Group is in your hands.",
               O("Hattı yeniden kur (tarihî) || Re-form the line (historical)", "Geri çekil ve tahkim et || Withdraw and fortify", "Osmanlı ordusu Filistin'de yeni bir hat kurdu. || The Ottoman army set up a new line in Palestine.", [["buff", "Turkey", "def", 1.1, 20], ["stab", "Turkey", -2]]),
               O("Kudüs'ü geri al || Retake Jerusalem", "Kumar || A gamble", "Osmanlı karşı taarruzu çıkmaza girdi. || The Ottoman counterattack stalled.", [["troops", "Turkey", -6], ["buff", "Turkey", "att", 1.1, 6]])),
   "United Kingdom": R("Noel hediyesi olarak Kudüs'ü Lloyd George'a sundun. Arap ve Yahudi vaatleri çatışıyor. || You offered Jerusalem to Lloyd George as a Christmas present. Promises to Arabs and Jews conflict.",
               O("Allenby'yi Şam'a yönlendir (tarihî) || Send Allenby to Damascus (historical)", "Zafer yürüyüşü sürer || The victory march goes on", "İngiliz ordusu Filistin'de ilerlemeyi sürdürdü. || The British army pressed on in Palestine.", [["buff", "United Kingdom", "att", 1.15, 12], ["rel", "United Kingdom", "Turkey", -4]]),
               O("Batı Cephesi'ne takviye gönder || Send reinforcements to the West", "Batı öncelikli || The West comes first", "Doğu Akdeniz'de ilerleme yavaşladı. || Progress slowed in the Eastern Mediterranean.", [["troops", "France", 2], ["stab", "United Kingdom", 1]]))},
  icon="flag", scene="pre_siege")

M("spring_1918", 1918, 3, "Kaiserschlacht: 1918 Bahar Taarruzu || Kaiserschlacht: The 1918 Spring Offensive",
  "Ludendorff, Rusya'dan boşalan tümenlerle Amerikalılar gelmeden Batı'da kesin sonuç arıyor. İlk günlerde fırtına birlikleri İngiliz hattını yardı; ama ikmal hatları uzuyor. || Ludendorff, with divisions freed from Russia, seeks a decision in the West before the Americans arrive. In the first days stormtroopers tore through the British line, but supply lines are stretching.",
  [["troops", "United Kingdom", -8], ["troops", "France", -4], ["troops", "Germany", -6], ["stab", "United Kingdom", -3]],
  {"Germany": R("İlerleme hızlı ama kayıplar da ağır; rezervler eriyor. Hedef Amiens mi, Kanal limanları mı? || Progress is rapid but losses are heavy; reserves are melting away. Is the target Amiens or the Channel ports?",
                O("Amiens'e yüklen (tarihî) || Press on Amiens (historical)", "Sonuç alacak ya da tükenecek || Succeed or run dry", "Alman ordusu Amiens'e yaklaştı ama ikmal tıkandı. || The German army neared Amiens but supply stalled.", [["buff", "Germany", "att", 1.2, 8], ["troops", "Germany", -8], ["stab", "Germany", -2]]),
                O("Kanal limanlarına yönel || Head for the Channel ports", "İngiltere'yi kopar || Cut off Britain", "Alman saldırısı Flandre'ye kaydı. || The German attack shifted to Flanders.", [["buff", "Germany", "att", 1.1, 8], ["troops", "Germany", -5]])),
   "United Kingdom": R("5. Ordu dağıldı; Fransa ile aranızdaki bağlantı kopmak üzere. Foch'a ortak komuta mı verilecek? || The Fifth Army has broken; the link with the French is about to snap. Will Foch be given unified command?",
                O("Foch'u başkomutan yap (tarihî) || Make Foch supreme commander (historical)", "Ortak komuta || Unified command", "İtilaf orduları Foch'un komutasında birleşti. || The Entente armies united under Foch.", [["rel", "United Kingdom", "France", 10], ["buff", "United Kingdom", "def", 1.15, 10]]),
                O("Bağımsız komutayı sürdür || Keep independent command", "Eşgüdüm zayıf || Weak coordination", "İngiliz komutası bağımsız kaldı. || British command stayed independent.", [["rel", "United Kingdom", "France", -5], ["troops", "United Kingdom", -3]])),
   "France": R("İngiliz hattı yarıldı; Paris tekrar tehlikede. Pétain rezervleri nereye yığacak? || The British line has split; Paris is in danger again. Where will Pétain pile up the reserves?",
                O("Rezervleri Amiens'e kaydır (tarihî) || Shift reserves to Amiens (historical)", "Müttefiki kurtar || Save the ally", "Fransız birlikleri Amiens hattını kapattı. || French troops sealed the Amiens line.", [["rel", "France", "United Kingdom", 8], ["troops", "France", -3]]),
                O("Paris'i koru || Protect Paris", "Kendi başkentini önceliklendir || Prioritise your own capital", "Fransa Paris'i kollayacak şekilde dizildi. || France deployed to cover Paris.", [["rel", "France", "United Kingdom", -6], ["stab", "France", 2]]))},
  icon="tank", scene="ww1_assault")

M("amiens", 1918, 8, "Amiens: Alman Ordusunun Kara Günü || Amiens: The Black Day of the German Army",
  "8 Ağustos'ta tanklar ve sürpriz topçu ateşiyle yapılan Müttefik taarruzu Alman hattını yırttı; Ludendorff buna 'Alman ordusunun kara günü' dedi. 'Yüz Gün' taarruzları başlıyor. || On 8 August a Allied attack with tanks and surprise artillery tore the German line; Ludendorff called it 'the black day of the German Army'. The Hundred Days offensives begin.",
  [["troops", "Germany", -8], ["stab", "Germany", -5], ["buff", "United Kingdom", "att", 1.1, 10]],
  {"Germany": R("Moral çöküyor; esirler teslim oluyor. Komuta kademesi barış sinyalini düşünmeye başladı. || Morale is collapsing; prisoners are surrendering. The high command begins considering a peace signal.",
                O("Hindenburg Hattı'na çekil (tarihî) || Fall back to the Hindenburg Line (historical)", "Orduyu koru || Preserve the army", "Alman ordusu Hindenburg Hattı'na çekildi. || The German army fell back to the Hindenburg Line.", [["buff", "Germany", "def", 1.15, 12], ["stab", "Germany", -2]]),
                O("Her mevziyi tut || Hold every position", "Ağır kayıp || Heavy losses", "Alman komutası geri çekilmeyi yasakladı. || German command forbade retreat.", [["buff", "Germany", "def", 1.2, 6], ["troops", "Germany", -8], ["stab", "Germany", -4]])),
   "United Kingdom": R("Tank ve piyade eşgüdümü işledi. Şimdi taarruzu genişletmeli misin? || The tank–infantry coordination worked. Should you widen the offensive?",
                O("Yüz Gün taarruzunu sürdür (tarihî) || Continue the Hundred Days (historical)", "Baskıyı hiç kesme || Never ease the pressure", "İtilaf orduları sürekli taarruza geçti. || The Entente armies went onto a continuous offensive.", [["buff", "United Kingdom", "att", 1.15, 12], ["troops", "United Kingdom", -4]]),
                O("Mevzileri tahkim et || Consolidate the ground", "Yavaş ama güvenli || Slow but safe", "Müttefikler kazanılan yerleri tahkim etti. || The Allies consolidated their gains.", [["stab", "United Kingdom", 2]])),
   "France": R("Foch 'Hepsi taarruz!' dedi. Fransız ordusu da büyük taarruza katılmalı mı? || Foch said 'Everybody to battle!' Should the French army join the great offensive?",
                O("Genel taarruza katıl (tarihî) || Join the general offensive (historical)", "Zafer yakın || Victory is near", "Fransız orduları Meuse–Argonne'a doğru yüklendi. || French armies pushed toward the Meuse–Argonne.", [["buff", "France", "att", 1.15, 12], ["troops", "France", -4]]),
                O("Seçici taarruz yap || Attack selectively", "Daha az kayıp || Fewer losses", "Fransa sınırlı taarruzlarla yetindi. || France made do with limited attacks.", [["stab", "France", 2]]), )},
  icon="tank", scene="ww1_assault")

M("mudros", 1918, 10, "Mondros Mütarekesi || The Armistice of Mudros",
  "Bulgaristan ve Filistin cepheleri çöktü; Osmanlı hükûmeti Limni'deki Agamemnon zırhlısında İngilizlerle ateşkes görüşüyor. Şartlar ağır: Boğazlar açılacak, ordu terhis edilecek. || The Bulgarian and Palestine fronts have collapsed; the Ottoman government is negotiating an armistice with the British aboard HMS Agamemnon at Lemnos. The terms are harsh: the Straits to be opened, the army demobilized.",
  [["peace", "Turkey", "United Kingdom"], ["stab", "Turkey", -8]],
  {"Turkey": R("Rauf Bey şartları pazarlıkla hafifletmeye çalışıyor; ama cephe yok. Mütareke imzalamak ağır, imzalamamak daha ağır. || Rauf Bey tries to soften the terms by bargaining; but the front is gone. Signing an armistice is heavy, not signing heavier.",
               O("Mütarekeyi imzala (tarihî) || Sign the armistice (historical)", "Savaşı bitir || End the war", "Osmanlı hükûmeti Mondros'u imzaladı. || The Ottoman government signed Mudros.", [["peace", "Turkey", "United Kingdom"], ["stab", "Turkey", -4], ["rel", "Turkey", "United Kingdom", 4]]),
               O("Direnişi sürdür || Keep resisting", "Tükenmiş ordu, riskli || An exhausted army, risky", "Hükûmet bir süre daha pazarlık etti. || The government haggled a little longer.", [["stab", "Turkey", -6], ["buff", "Turkey", "def", 1.05, 8]])),
   "United Kingdom": R("Osmanlı'dan şartsız teslim yakın. Boğazlar ve Irak petrolü için ne kadar ileri gideceksin? || An Ottoman unconditional surrender is near. How far will you go for the Straits and Iraqi oil?",
               O("Ağır şartlar dayat (tarihî) || Impose harsh terms (historical)", "Boğazlar ve işgal hakkı || The Straits and occupation rights", "Londra Boğazlar'ın açılmasını ve ordunun terhisini şart koştu. || London demanded the opening of the Straits and demobilization.", [["rel", "United Kingdom", "Turkey", -6], ["buff", "United Kingdom", "att", 1.05, 6]]),
               O("Daha esnek şartlar öner || Offer milder terms", "Barışı kolaylaştır || Make peace easier", "Londra bir miktar esneklik gösterdi. || London showed some flexibility.", [["rel", "United Kingdom", "Turkey", 4], ["stab", "Turkey", 3]]))},
  icon="treaty", scene="peace")

M("versailles", 1919, 6, "Versay Antlaşması || The Treaty of Versailles",
  "Aynalar Salonu'nda imzalanan antlaşma Almanya'ya savaş suçu yüklüyor: büyük tazminat, toprak kayıpları, ordu sınırlaması. Wilson 'Ulusların Cemiyeti'ni savunuyor; Clemenceau güvenlik istiyor. || The treaty signed in the Hall of Mirrors places war guilt on Germany: huge reparations, territorial losses, army limits. Wilson champions a League of Nations; Clemenceau wants security.",
  [["stab", "Germany", -8], ["gold", "Germany", -1.0], ["rel", "Germany", "France", -8]],
  {"Germany": R("Heyet 'diktat' olarak gördüğü metni imzalamak zorunda; reddetmek işgali getirir. || The delegation must sign a text it sees as a 'diktat'; refusing means occupation.",
                O("İmzala (tarihî) || Sign (historical)", "Yeniden doğuş için zaman kazan || Buy time for recovery", "Almanya Versay'ı imzaladı; millî gurur yaralandı. || Germany signed Versailles; national pride was wounded.", [["stab", "Germany", -4], ["rel", "Germany", "France", -4], ["rel", "Germany", "United Kingdom", 4]]),
                O("Reddet || Refuse", "İşgal riski || Risk of occupation", "Berlin imzayı reddetti; Müttefikler yürüyüş tehdidinde bulundu. || Berlin refused to sign; the Allies threatened to march.", [["stab", "Germany", -8], ["rel", "Germany", "France", -10], ["troops", "Germany", -3]])),
   "France": R("Clemenceau Ren sınırında güvence istiyor; Wilson ve Lloyd George ise ılımlı. || Clemenceau wants guarantees on the Rhine; Wilson and Lloyd George are moderate.",
                O("Sert şartları savun (tarihî) || Insist on harsh terms (historical)", "Güvenlik ve tazminat || Security and reparations", "Fransa ağır tazminat ve Ren işgali elde etti. || France secured heavy reparations and a Rhineland occupation.", [["gold", "France", 2.0], ["rel", "France", "Germany", -8], ["stab", "France", 3]]),
                O("Ilımlı bir barışa razı ol || Accept a moderate peace", "Uzlaşı || Compromise", "Paris müttefik uzlaşısını kabul etti. || Paris accepted the Allied compromise.", [["rel", "France", "United Kingdom", 4], ["rel", "France", "Germany", 3]])),
   "United States of America": R("Wilson'ın On Dört Maddesi'nin kaderi belli olmak üzere; Senato Uluslar Cemiyeti'ne şüpheli. || The fate of Wilson's Fourteen Points is about to be decided; the Senate is wary of the League of Nations.",
                O("Ulusların Cemiyeti'ni destekle (tarihî) || Back the League of Nations (historical)", "Yeni dünya düzeni || A new world order", "Wilson Ulusların Cemiyeti için kampanya yürüttü; Senato onaylamadı. || Wilson campaigned for the League; the Senate did not ratify.", [["rel", "United States of America", "United Kingdom", 4], ["stab", "United States of America", -3]]),
                O("Avrupa'dan uzak dur || Stay out of Europe", "İzolasyon || Isolation", "Amerika Avrupa işlerinden çekildi. || America withdrew from European affairs.", [["stab", "United States of America", 3], ["rel", "United States of America", "France", -4]]), )},
  icon="treaty", scene="peace")

M("sevres", 1920, 8, "Sevr Antlaşması || The Treaty of Sèvres",
  "Osmanlı heyeti Sevr'de İtilaf'ın dayattığı antlaşmayı imzaladı: İzmir ve Doğu Trakya Yunanistan'a, Boğazlar uluslararası, Doğu'da Ermeni ve Kürt bölgeleri öngörülüyor. Ankara bu metni tanımıyor. || The Ottoman delegation signed the treaty imposed by the Entente at Sèvres: Izmir and Eastern Thrace to Greece, the Straits internationalized, Armenian and Kurdish zones foreseen in the East. Ankara does not recognise the text.",
  [["rel", "Turkey", "Greece", -8], ["rel", "Greece", "Turkey", -6], ["stab", "Greece", 4]],
  {"Turkey": R("İstanbul hükûmeti imzaladı ama Anadolu'da Millî Mücadele sürüyor; Büyük Millet Meclisi antlaşmayı reddediyor. || The Istanbul government signed, but the National Struggle continues in Anatolia; the Grand National Assembly rejects the treaty.",
               O("Sevr'i reddet, savaşa devam (tarihî) || Reject Sèvres and fight on (historical)", "Millî egemenlik || National sovereignty", "TBMM Sevr'i tanımadığını ilan etti. || The Grand National Assembly declared that it did not recognise Sèvres.", [["stab", "Turkey", 6], ["buff", "Turkey", "def", 1.15, 20], ["rel", "Turkey", "United Kingdom", -6]]),
               O("Müzakere yolunu aç || Open the road to negotiation", "Taviz || Concessions", "Ankara İtilaf ile gizli görüşme yürüttü. || Ankara held secret talks with the Entente.", [["rel", "Turkey", "United Kingdom", 4], ["stab", "Turkey", -4]])),
   "Greece": R("Venizelos'un Büyük Yunanistan hayali gerçek oluyor; ama Anadolu'da direniş artıyor. || Venizelos's dream of a Greater Greece is coming true; but resistance grows in Anatolia.",
               O("Anadolu'ya ilerle (tarihî) || Advance into Anatolia (historical)", "Sevr'i silahla uygula || Enforce Sèvres by arms", "Yunan ordusu iç Anadolu'ya yöneldi. || The Greek army moved into inner Anatolia.", [["buff", "Greece", "att", 1.1, 12], ["rel", "Greece", "Turkey", -8], ["rel", "Greece", "United Kingdom", 4]]),
               O("Kazanımları tahkim et || Consolidate your gains", "İzmir ve Trakya yeter || Izmir and Thrace suffice", "Yunanistan işgal bölgelerini tahkim etti. || Greece consolidated the occupation zones.", [["buff", "Greece", "def", 1.1, 12], ["stab", "Greece", 2]]))},
  icon="treaty", scene="peace")
